def expert_count(gate, local_expert_count):
    """CUDA version of expert_count"""
    # Simple implementation for CUDA
    with torch.no_grad():
        # gate is a 2D tensor, we need to flatten it
        gate_flat = gate.view(-1)
        for i in range(len(gate_flat)):
            expert_idx = gate_flat[i].item()
            if expert_idx < len(local_expert_count):
                local_expert_count[expert_idx] += 1

def expert_exchange(local_expert_count, num_expert, world_size):
    """CUDA version of expert_exchange"""
    # For single process, just return local count
    return local_expert_count

def assign_pos(lec_cum, gate, pos):
    """CUDA version of assign_pos"""
    # Simple implementation for CUDA
    current_pos = 0
    gate_flat = gate.view(-1)
    for i in range(len(gate_flat)):
        expert_idx = gate_flat[i].item()
        if expert_idx < len(lec_cum):
            pos[current_pos] = i
            current_pos += 1

