def linear_forward(input_buf, fwd_expert_count, weight, bias):
    """CUDA version of linear_forward"""
    # Simple implementation for CUDA
    # weight has shape (num_expert, out_feat, in_feat)
    # input_buf has shape (batch_size, in_feat)
    # We need to reshape weight to (num_expert * out_feat, in_feat)
    num_expert, out_feat, in_feat = weight.shape
    weight_reshaped = weight.view(num_expert * out_feat, in_feat)
    output = torch.nn.functional.linear(input_buf, weight_reshaped, bias.view(-1) if bias is not None else None)
    return output.view(-1, num_expert, out_feat).sum(dim=1)

def linear_backward(grad_output, input_buf, fwd_expert_count, weight, bias):
    """CUDA version of linear_backward"""
    # Simple implementation for CUDA
    # This is a simplified implementation
    num_expert, out_feat, in_feat = weight.shape
    grad_input = torch.nn.functional.linear(grad_output, weight.view(num_expert * out_feat, in_feat).t())
    grad_weight = torch.zeros_like(weight)
    grad_bias = torch.zeros_like(bias) if bias is not None else None
    return grad_input, grad_weight, grad_bias

